      getOptLevel() != CodeGenOptLevel::None)
    addPass(createCleanupLocalDynamicTLSLegacyPass());

  addPass(createX86GlobalBaseRegLegacyPass());
  addPass(createX86ArgumentStackSlotLegacyPass());
  return false;
}

